INSERT INTO public.projects (slug, title, category, results, image, tags, description, full_description, metrics, analytics_images, platforms, timeline, budget) VALUES
('romance-author-campaign', 'Romance Author Campaign', 'Facebook & Instagram Ads', '3.2M Impressions, 12K Sales', '/romance-book-cover-promotion.jpg', ARRAY['Facebook', 'Instagram', 'E-book'], 'A targeted Facebook and Instagram ads campaign for a romance author that resulted in exceptional engagement and sales conversion.', 'This comprehensive romance author campaign leveraged the power of Facebook and Instagram advertising to reach potential readers across multiple demographics. Through careful audience targeting and compelling ad creatives, we achieved industry-leading metrics in both impressions and conversions.', '{"metrics": [{"label": "Impressions", "value": "3.2M"}, {"label": "Sales", "value": "12K"}, {"label": "Click-Through Rate", "value": "8.5%"}, {"label": "Cost Per Sale", "value": "$2.50"}]}', ARRAY[]::text[], ARRAY['Facebook Ads', 'Instagram Ads', 'E-Book Platform'], '6 months', 'Custom'),
('mystery-thriller-website', 'Mystery Thriller Website', 'Author Website Design', '5K Monthly Visitors', '/mystery-thriller-book-website-design.jpg', ARRAY['Web Design', 'Responsive', 'E-commerce'], 'Professional author website with e-commerce integration, allowing direct book sales and reader engagement.', 'A custom-built mystery author website featuring a professional design, integrated e-commerce functionality, and reader engagement tools. The site successfully drives monthly visitor traffic and enables direct book sales.', '{"metrics": [{"label": "Monthly Visitors", "value": "5K"}, {"label": "Bounce Rate", "value": "32%"}, {"label": "Avg Session Time", "value": "3m 24s"}, {"label": "Conversion Rate", "value": "6.2%"}]}', ARRAY[]::text[], ARRAY['Website Design', 'E-commerce', 'Email Integration'], '3 months', '$499/month'),
('sci-fi-amazon-campaign', 'Sci-Fi Amazon Campaign', 'Amazon Ads & Google Ads', '8.5K Sales, 450% ROI', '/science-fiction-book-amazon-promotion.jpg', ARRAY['Amazon Ads', 'Google Ads', 'Sci-Fi'], 'Multi-platform advertising strategy combining Amazon Ads and Google Ads for maximum reach and ROI.', 'A strategic multi-platform approach combining Amazon Ads and Google Ads to maximize visibility and sales for a science fiction series. Our optimization strategy resulted in exceptional ROI through careful keyword research and bid management.', '{"metrics": [{"label": "Total Sales", "value": "8.5K"}, {"label": "ROI", "value": "450%"}, {"label": "Ad Spend", "value": "$4,200"}, {"label": "Revenue Generated", "value": "$23,400"}]}', ARRAY['/images/whisk-fd7b6ad08bc004ba03844515e496ad48dr.jpeg', '/images/ads.png'], ARRAY['Amazon Ads', 'Google Ads', 'Keyword Optimization'], '4 months', 'Custom'),
('self-help-author-bundle', 'Self-Help Author Bundle', 'Multi-Platform Campaign', '2.1M Impressions, 28K Sales', '/self-help-book-marketing-campaign.jpg', ARRAY['Multi-Channel', 'Landing Page', 'Email'], 'Comprehensive marketing campaign across multiple platforms with dedicated landing pages and email sequences.', 'An all-encompassing marketing campaign for a self-help author featuring coordinated efforts across Google Ads, Facebook Ads, dedicated landing pages, and email marketing sequences to build an engaged audience.', '{"metrics": [{"label": "Impressions", "value": "2.1M"}, {"label": "Sales", "value": "28K"}, {"label": "Email Subscribers", "value": "15K"}, {"label": "Landing Page Conversion", "value": "9.8%"}]}', ARRAY[]::text[], ARRAY['Google Ads', 'Facebook Ads', 'Email Marketing', 'Landing Pages'], '5 months', 'Custom'),
('childrens-book-launch', 'Children''s Book Launch', 'Complete Marketing Package', '15K Pre-Orders', '/children-book-launch-marketing.jpg', ARRAY['Website', 'Social Media', 'PR'], 'Full-service launch campaign including website, social media strategy, and PR outreach for a children''s book series.', 'A complete launch strategy for a children''s book series including custom website development, comprehensive social media campaigns, and strategic PR outreach to generate maximum buzz and pre-orders.', '{"metrics": [{"label": "Pre-Orders", "value": "15K"}, {"label": "Social Media Reach", "value": "850K"}, {"label": "Press Mentions", "value": "24"}, {"label": "Media Value", "value": "$45K"}]}', ARRAY[]::text[], ARRAY['Website Design', 'Social Media', 'PR Outreach', 'Influencer Marketing'], '3 months', 'Custom'),
('non-fiction-publisher-site', 'Non-Fiction Publisher Site', 'Publisher Website', '8K Daily Visitors', '/publisher-website-design-platform.jpg', ARRAY['Web Design', 'CMS', 'Multi-Author'], 'Custom CMS platform for a non-fiction publisher managing multiple author profiles and book listings.', 'A sophisticated custom CMS platform designed for a non-fiction publisher to manage 50+ authors and 300+ book listings. The platform includes author portals, advanced analytics, and e-commerce integration.', '{"metrics": [{"label": "Daily Visitors", "value": "8K"}, {"label": "Books Listed", "value": "300+"}, {"label": "Authors Managed", "value": "50+"}, {"label": "Monthly Revenue", "value": "$125K"}]}', ARRAY[]::text[], ARRAY['Custom CMS', 'Multi-Author Management', 'E-commerce', 'Analytics Dashboard'], '6 months', '$499/month')
